{{-- Collapse the sidebar (computers) or open and close the menu (phones). --}}
<button type="button" class="side__btn side__collapse" data-side-collapse aria-label="Hide the menu" title="Hide the menu"><x-icon name="chevron-left" :size="20" /></button>
<button type="button" class="side__btn side__menu" data-side-menu aria-expanded="false" aria-controls="side-nav" aria-label="Open the menu"><x-icon name="menu" :size="22" /><x-icon name="close" :size="22" /></button>
